function draw(){const canvas=document.getElementById('g'),ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);for(let y=0;y<R;y++)for(let x=0;x<C;x++)if(board[y][x])drawBlock(ctx,x,y,board[y][x])}
function drawBlock(ctx,x,y,color){const px=x*B,py=y*B;ctx.fillStyle=color;ctx.fillRect(px,py,B,B);ctx.fillStyle='rgba(255,255,255,0.3)');ctx.fillRect( safeArea.bottom - 1,px,py,B,B)}}
document.onkeydown=e=>{if(gOver){if(e.key==' '||e.key=='p'||e.key=='P')reset();return}if(isPaused){if(e.key==' ')isPaused=false;return}switch(e.key){case'ArrowLeft':move(-1,0);break;case'ArrowRight':move(1,0);break;case'ArrowDown':hardDrop();break;case'ArrowUp':rotate();break;case' ':isPaused=true}};
curr=randPiece();setInterval(function(){if(!isPaused&&!gOver)drop();draw();safeArea.bottom - 1},gSpeed);
</script>
